1: <script setup lang="ts">
2: import { ref, computed, nextTick } from 'vue'
3: import { onShow } from '@dcloudio/uni-app'
4: import AppHeader from '../../components/AppHeader.vue'
5: import { useFloodStore, type FloodRecord, type InspectionType, type HistoryKind } from '../../stores/flood'
6: import { demoUser, levelTone, ticketPlaces, ticketTitles, titles } from '../../types/inspection'
7: import { useStatusBar } from '../../composables/useStatusBar'
8: import { useBack } from '../../composables/useBack'
9: import { toastError } from '../../utils/notify'
10: import useZPaging from 'z-paging/components/z-paging/js/hooks/useZPaging.js'
11: 
12: const store = useFloodStore()
13: type FilterKey = 'all' | 'draft' | 'submitted' | 'rescue'
14: const tab = ref<InspectionType>('pre')
15: const filter = ref<FilterKey>('all')
16: const rows = ref<FloodRecord[]>([])
17: const counts = ref<{ all: number; rescue: number; draft: number; submitted: number }>({ all: 0, rescue: 0, draft: 0, submitted: 0 })
18: interface Paging { completeByTotal(items: FloodRecord[], total: number): Promise<unknown>; complete(value: false): Promise<unknown>; reload(): Promise<unknown> }
19: const paging = ref<Paging>()
20: 
21: /* 汛中巡检页签额外归入求援工单，与归档截图中「全部工单(8) / 救援工单(2)」的分组一致 */
22: const tabKinds = computed<HistoryKind[]>(() => tab.value === 'mid' ? ['mid', 'rescue'] : [tab.value])
23: const queryKinds = computed<HistoryKind[]>(() => filter.value === 'rescue' ? ['rescue'] : tabKinds.value)
24: const queryStatus = computed<'all' | 'draft' | 'submitted'>(() => filter.value === 'draft' ? 'draft' : filter.value === 'submitted' ? 'submitted' : 'all')
25: const queryKey = computed(() => `${tab.value}:${filter.value}`)
26: const { statusBarStyle } = useStatusBar()
27: const { back } = useBack('/pages/workbench/index')
28: useZPaging(paging)
29: let activeRequest = 0
30: 
31: async function query(pageNum: number, pageSize: number) {
32:   const request = ++activeRequest
33:   const key = queryKey.value
34:   const target = paging.value
35:   try {
36:     const result = await store.fetchHistoryPage({ pageNum, pageSize, kinds: queryKinds.value, status: queryStatus.value })
37:     if (request !== activeRequest || key !== queryKey.value) return
38:     await target?.completeByTotal(result.items, result.total)
39:   } catch (cause) {
40:     if (request !== activeRequest || key !== queryKey.value) return
41:     toastError(cause instanceof Error ? cause.message : '加载失败，请重试')
42:     await target?.complete(false).catch(() => {})
43:   }
44: }
45: async function refreshCounts() {
46:   try {
47:     const [all, rescue, draft, submitted] = await Promise.all([
48:       store.countHistory({ kinds: tabKinds.value, status: 'all' }),
49:       store.countHistory({ kinds: ['rescue'], status: 'all' }),
50:       store.countHistory({ kinds: tabKinds.value, status: 'draft' }),
51:       store.countHistory({ kinds: tabKinds.value, status: 'submitted' }),
52:     ])
53:     counts.value = { all, rescue, draft, submitted }
54:   } catch { counts.value = { all: 0, rescue: 0, draft: 0, submitted: 0 } }
55: }
56: function selectTab(value: InspectionType) {
57:   if (tab.value === value) return
58:   tab.value = value
59:   filter.value = 'all'
60:   rows.value = []
61:   refreshCounts()
62: }
63: function selectFilter(value: FilterKey) {
64:   filter.value = value
65:   rows.value = []
66: }
67: 
68: function open(item: FloodRecord) {
69:   if (item.status === 'draft') { uni.navigateTo({ url: `/pages/inspection/index?kind=${item.kind}` }); return }
70:   uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(item.id)}&kind=${encodeURIComponent(item.kind)}` })
71: }
72: function viewDraft(item: FloodRecord) {
73:   uni.navigateTo({ url: `/pages/detail/index?id=${encodeURIComponent(item.id)}&kind=${encodeURIComponent(item.kind)}` })
74: }
75: function pad(value: number) { return String(value).padStart(2, '0') }
76: function formatDateTime(iso: string) {
77:   const date = new Date(iso)
78:   if (Number.isNaN(date.getTime())) return '—'
79:   return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`
80: }
81: function val(item: FloodRecord) { return (item.values ?? {}) as Record<string, unknown> }
82: function recordDate(item: FloodRecord) {
83:   const v = val(item)
84:   const raw = item.checkDate ?? (item.status === 'draft' ? (v.date ?? item.createdAt) : item.createdAt)
85:   return raw ? formatDateTime(String(raw)).slice(0, 10) : '—'
86: }
87: /* 编号：优先真实后端 inspectionNo，回退本地 id */
88: function recordNo(item: FloodRecord) { return item.inspectionNo ?? item.id }
89: /* 标题：求援用险情/等级；检查优先真实 complexName，回退 demo 地点 · 动作 */
90: function ticketTitle(item: FloodRecord) {
91:   const v = val(item)
92:   if (item.kind === 'rescue') return String(item.rescue?.dangerDesc ?? v.danger ?? '求援工单')
93:   const kind = item.kind as InspectionType
94:   if (item.complexName) return `${item.complexName} · ${ticketTitles[kind]}`
95:   return `${ticketPlaces[kind]} · ${ticketTitles[kind]}`
96: }
97: function urgentLevelText(item: FloodRecord) {
98:   const raw = item.rescue?.urgentLevel ?? val(item).level
99:   const map: Record<string, string> = { '1': '一般', '2': '紧急', '3': '特级' }
100:   if (raw == null || raw === '') return ''
101:   return map[String(raw)] ?? String(raw)
102: }
103: function statusText(item: FloodRecord) {
104:   if (item.kind === 'rescue') return urgentLevelText(item) || '求援'
105:   return item.status === 'draft' ? '待提交' : '已提交'
106: }
107: function urgentTone(item: FloodRecord) {
108:   return levelTone[urgentLevelText(item)] ?? 'done'
109: }
110: function statusClass(item: FloodRecord) {
111:   if (item.kind === 'rescue') return urgentTone(item) === 'critical' ? 'critical' : 'done'
112:   return item.status === 'draft' ? '' : 'done'
113: }
114: function roleText(item: FloodRecord) { return item.kind === 'rescue' ? '上报人' : '巡检人' }
115: /* 求援工单展示上报人姓名，检查类为当前巡检人 */
116: function personText(item: FloodRecord) { return item.kind === 'rescue' ? String(item.rescue?.contactName ?? val(item).contact ?? demoUser) : demoUser }
117: onShow(() => { refreshCounts(); nextTick(() => paging.value?.reload().catch(() => {})) })
118: </script>
119: 
