1: @font-face{font-family:'Noto Sans SC:Regular';src:url('https://static.figma.com/font/NotoSansSC-VF_2') format('woff2');font-style:normal;font-weight:400}
2: @font-face{font-family:'Noto Sans SC:Medium';src:url('https://static.figma.com/font/NotoSansSC-VF_2') format('woff2');font-style:normal;font-weight:500}
3: @font-face{font-family:'Noto Sans SC:Bold';src:url('https://static.figma.com/font/NotoSansSC-VF_2') format('woff2');font-style:normal;font-weight:700}
4: @font-face{font-family:'Plus Jakarta Sans:Regular';src:url('https://static.figma.com/font/PlusJakartaSans_wght__2') format('woff2');font-style:normal;font-weight:400}
5: @font-face{font-family:'Plus Jakarta Sans:Medium';src:url('https://static.figma.com/font/PlusJakartaSans_wght__2') format('woff2');font-style:normal;font-weight:500}
6: @font-face{font-family:'Plus Jakarta Sans:SemiBold';src:url('https://static.figma.com/font/PlusJakartaSans_wght__2') format('woff2');font-style:normal;font-weight:600}
7: 
8: /* ===== 设计令牌（取自 C:\Users\Administrator\Downloads\归档 截图取色） ===== */
9: :root{
10:   --c-bg:#f7f9fd;
11:   --c-surface:#ffffff;
12:   --c-fill:#f2f4f8;
13:   --c-fill-strong:#e6e8ec;
14:   --c-line:#e6e8ec;
15:   --c-text:#191c1f;
16:   --c-text-2:#424655;
17:   --c-text-3:#737686;
18:   --c-brand:#075ed1;
19:   --c-brand-soft:#edf1ff;
20:   --c-warn:#ef7f13;
21:   --c-warn-soft:#fff0dc;
22:   --c-critical:#c31d24;
23:   --c-critical-soft:#ffe9e8;
24:   --c-orange:#fe9c2d;
25:   --r-card:12px;
26:   --r-ctl:8px;
27:   --shadow-card:0 1px 2px #0000000d;
28: }
29: 
30: page{
31:   min-height:100vh;
32:   background:var(--c-bg);
33:   color:var(--c-text);
34:   font-family:'Noto Sans SC:Medium','Noto Sans SC',-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;
35:   font-size:18px;
36:   font-weight:400;
37:   line-height:1.5;
38:   box-sizing:border-box;
39: }
40: view,text,image,input,textarea,scroll-view,label{box-sizing:border-box;margin:0;padding:0;border:0 solid}
41: image{display:block;max-width:100%}
42: input,textarea{font:inherit;color:inherit;background:transparent;outline:none;border:0 solid}
43: 
44: /* 屏幕容器：页头 56px（与参考站一致）+ 底部操作栏 72px */
45: .screen{min-height:100vh;min-height:100dvh;background:var(--c-bg);padding:calc(56px + var(--status-bar-height,0px)) 0 calc(72px + env(safe-area-inset-bottom));position:relative;margin:auto;max-width:720px;box-sizing:border-box}
46: .form-screen{padding-bottom:calc(72px + env(safe-area-inset-bottom))}
47: 
48: /* 固定页头：高 56px（对齐参考站 .topbar），标题 18px/700 */
49: .app-header{position:fixed;z-index:20;top:var(--status-bar-height,0px);left:0;right:0;margin:0 auto;max-width:720px;height:56px;display:flex;align-items:center;justify-content:center;background:rgba(247,249,253,.88);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);box-shadow:0 1px 8px #0000000a}
50: .app-header-title{font-size:18px;font-weight:700;line-height:26px}
51: .app-back{position:absolute;left:14px;top:0;height:56px;display:flex;align-items:center}
52: .app-back-glyph{font-family:sans-serif;font-weight:400;font-size:32px;line-height:1}
53: 
54: /* ===== 工作台 ===== */
55: .workspace{display:flex;gap:12px;padding:18px 16px}
56: .workspace-aside{width:80px;display:flex;flex-direction:column;gap:8px;flex:none}
57: .side-tab{height:76px;text-align:center;border-radius:12px;background:var(--c-fill);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;font-size:14px;position:relative}
58: .side-tab-image{width:20px;height:20px}
59: .side-tab.active{background:var(--c-brand-soft);color:#004fd0}
60: .side-tab.active::before{content:'';position:absolute;left:0;top:8px;bottom:8px;width:4px;border-radius:0 9px 9px 0;background:#004fd0}
61: .apps{flex:1;min-width:0}
62: .section-title{height:38px;padding:0 12px;background:var(--c-surface);border-radius:var(--r-ctl);display:flex;align-items:center;justify-content:space-between;box-shadow:var(--shadow-card);font-size:16px;margin-bottom:8px}
63: .section-title-text{font-weight:700}
64: .section-title-count{font-size:13px;color:var(--c-text-2);background:var(--c-fill-strong);padding:2px 8px;border-radius:99px}
65: .app-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
66: .app-card{height:116px;text-align:center;background:var(--c-surface);border-radius:var(--r-card);box-shadow:var(--shadow-card);display:flex;flex-direction:column;align-items:center;justify-content:center}
67: .icon-well{width:48px;text-align:center;height:48px;border-radius:16px;display:grid;place-items:center;margin-bottom:6px;background:#eff6ffcc}
68: .icon-well-image{width:24px;height:24px}
69: .tone-1{background:#eef2ffcc}
70: .tone-2{background:#f0fdfacc}
71: .tone-3{background:#fffbeacc}
72: .app-card-title{font-size:16px;line-height:20px;font-weight:700}
73: .app-card-sub{font-size:12px;color:var(--c-text-2);line-height:14px}
74: 
75: /* 底部导航 */
76: .bottom-nav{position:fixed;z-index:20;bottom:0;left:0;right:0;margin:0 auto;max-width:720px;height:calc(64px + env(safe-area-inset-bottom));padding-bottom:env(safe-area-inset-bottom);background:rgba(247,249,253,.92);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);display:flex;justify-content:space-around;box-shadow:0 -2px 12px #0000000a}
77: .bottom-nav-item{flex:1;min-width:0;text-align:center;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:13px;color:#424655}
78: .bottom-nav-image{width:21px;height:21px;margin-bottom:2px}
79: .bottom-nav-label{font-size:12px;line-height:16px;white-space:nowrap}
80: .bottom-nav-item.selected{color:#004fd0}
81: .bottom-nav-item.selected .bottom-nav-image{filter:saturate(1.9)}
82: /* 带底部 tab 的页面主内容区：留出导航高度 */
83: .app-screen{padding-bottom:calc(64px + env(safe-area-inset-bottom))}
84: /* 带底部 tab 的页面主内容区：.screen 已留出页头高度，这里只补页头下的小间距
85:    参考站口径：home 首卡距页头 8px、housing 28px（见各页 .*-content 覆写） */
86: .screen-content{padding:8px 16px 16px}
87: 
88: /* 表单
89:    归档截图是 1x 设备像素（414×1953），故所有尺寸直接用截图度量值：
90:    内容区左右 14px、卡片宽 358px 内边距 10px、字段 pitch 44px、
91:    标签行高 20px、步进器高 24px、卡片圆角 10px */
92: .form-content{display:flex;flex-direction:column;gap:12px;padding:12px 14px}
93: .form-card{background:var(--c-surface);border-radius:10px;padding:12px 10px;box-shadow:var(--shadow-card);display:flex;flex-direction:column;gap:8px}
94: .field{display:flex;flex-direction:column;gap:4px}
95: /* 物业管理区域搜索：下拉浮层不挤占下方字段 */
96: .complex-control{position:relative}
97: .complex-picked{display:flex;align-items:center;justify-content:space-between;margin-top:8px}
98: .complex-picked-text{font-size:15px;color:#1a6fd6}
99: .complex-picked-clear{font-size:15px;color:#999;padding:2px 6px}
100: .complex-dropdown{position:absolute;left:0;right:0;top:calc(100% + 6px);z-index:18;border:1px solid #e6e6e6;border-radius:8px;max-height:240px;overflow-y:auto;background:#fff;box-shadow:0 8px 24px #0000001f}
101: .complex-option{padding:10px 12px;font-size:16px;color:#333;border-bottom:1px solid #f2f2f2}
102: .complex-option:last-child{border-bottom:none}
103: .complex-option.chosen{color:#1a6fd6;background:#f2f7ff}
104: .complex-option.muted{color:#999}
105: .field-label,.upload-label{font-size:15px;line-height:20px;display:block}
106: .upload-head{display:flex;align-items:center;justify-content:space-between}
107: .upload-head .upload-label{flex:none}
108: .upload-count{font-size:13px;color:var(--c-text-3);flex:none;line-height:20px}
109: .field-required{color:#ba1a1a}
110: .field-input,.field-textarea{background:var(--c-fill);border-radius:6px;padding:0 8px;font-size:15px;width:100%;display:block}
111: .field-input{height:56px;line-height:56px;display:flex;align-items:center}
112: /* 输入框中的原生 input 需继承容器尺寸 */
113: .field-input > input{width:100%;height:54px;line-height:54px;display:block;background:transparent;border:0;font-size:15px;color:var(--c-text);padding:0}
114: .field-input > input::placeholder{color:var(--c-text-3)}
